import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Day 6: BitBake Operators & Layer Creation","description":"","frontmatter":{},"headers":[],"relativePath":"day6-bitbake-operators-and-layer-creation.md","filePath":"day6-bitbake-operators-and-layer-creation.md"}'),n={name:"day6-bitbake-operators-and-layer-creation.md"};function o(r,e,l,d,p,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="day-6-bitbake-operators-layer-creation" tabindex="-1">Day 6: BitBake Operators &amp; Layer Creation <a class="header-anchor" href="#day-6-bitbake-operators-layer-creation" aria-label="Permalink to &quot;Day 6: BitBake Operators &amp; Layer Creation&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the order of parsing in BitBake and how variables are expanded</li><li>Differentiate between <code>+</code>, <code>=</code>, <code>?=</code>, <code>??=</code>, and <code>:=</code> operators</li><li>Utilize override syntax (<code>:append</code>, <code>:prepend</code>, <code>:remove</code>) safely</li><li>Create a custom software layer using the <code>bitbake-layers</code> utility</li><li>Structure a new layer correctly to isolate custom recipes from OE-Core</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day5-raspberry-pi-hardware-bringup.html">Day 5: Raspberry Pi Hardware Bring-Up</a></li><li>Familiarity with modifying <code>local.conf</code></li></ul></div><hr><h2 id="_1-bitbake-variable-assignment-operators" tabindex="-1">1. BitBake Variable Assignment Operators <a class="header-anchor" href="#_1-bitbake-variable-assignment-operators" aria-label="Permalink to &quot;1. BitBake Variable Assignment Operators&quot;">​</a></h2><p>BitBake processes all metadata files (<code>.conf</code>, <code>.bbclass</code>, <code>.bb</code>, <code>.bbappend</code>) sequentially. When multiple files define the same variable (like <code>IMAGE_INSTALL</code>), BitBake uses specific assignment operators to resolve conflicts.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Name</th><th>Behavior</th><th>Example</th></tr></thead><tbody><tr><td><code>=</code></td><td><strong>Hard Assignment</strong></td><td>Overwrites any previous value. Set at parse time, but can be overridden later in the parsing queue.</td><td><code>VAR = &quot;foo&quot;</code></td></tr><tr><td><code>?=</code></td><td><strong>Soft Default</strong></td><td>Sets the value <em>only if</em> it has not been set by a hard assignment before. If multiple <code>?=</code> exist, the first one encountered wins.</td><td><code>VAR ?= &quot;default&quot;</code></td></tr><tr><td><code>??=</code></td><td><strong>Weak Default</strong></td><td>The lowest priority assignment. If multiple <code>??=</code> exist, the <em>last</em> one encountered wins. Usually used in core classes.</td><td><code>VAR ??= &quot;weak&quot;</code></td></tr><tr><td><code>:=</code></td><td><strong>Immediate Expansion</strong></td><td>Evaluates and locks in the value <em>immediately</em> when parsed. Normal variables are expanded lazily at the end.</td><td><code>VAR := &quot;\${OTHER_VAR}&quot;</code></td></tr><tr><td><code>+=</code></td><td><strong>Append (Space)</strong></td><td>Appends a value with a leading space.</td><td><code>VAR += &quot;bar&quot;</code> -&gt; <code>foo bar</code></td></tr><tr><td><code>=+</code></td><td><strong>Prepend (Space)</strong></td><td>Prepends a value with a trailing space.</td><td><code>VAR =+ &quot;bar&quot;</code> -&gt; <code>bar foo</code></td></tr></tbody></table><h3 id="lazy-vs-immediate-expansion" tabindex="-1">Lazy vs. Immediate Expansion <a class="header-anchor" href="#lazy-vs-immediate-expansion" aria-label="Permalink to &quot;Lazy vs. Immediate Expansion&quot;">​</a></h3><p>By default, BitBake variables are expanded <strong>lazily</strong> (at the very end of the parsing process).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example of Lazy Expansion (Default)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;apple&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;orange&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># B evaluates to &quot;orange&quot; because expansion happens at the end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example of Immediate Expansion</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;apple&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;orange&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># C evaluates to &quot;apple&quot; because it was locked immediately</span></span></code></pre></div><hr><h2 id="_2-override-operators-append-and-prepend" tabindex="-1">2. Override Operators (<code>:append</code> and <code>:prepend</code>) <a class="header-anchor" href="#_2-override-operators-append-and-prepend" aria-label="Permalink to &quot;2. Override Operators (\`:append\` and \`:prepend\`)&quot;">​</a></h2><p>While <code>+=</code> is useful, it is applied strictly in the order BitBake parses files. If you use <code>+=</code> in your recipe, but a core class overwrites it with <code>=</code> later, your append is lost.</p><p>To guarantee your additions are applied, use the override operators. These are guaranteed to be evaluated at the very end of the parsing phase, regardless of where they are defined.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Correct way to append packages to an image</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_INSTALL:append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot; busybox-syslog&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Correct way to prepend a search path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILESEXTRAPATHS:prepend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">THISDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/files:&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Removing a specific item from a list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_INSTALL:remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot; dropbear&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">SPACING IS CRITICAL</p><p>Unlike <code>+=</code>, the override operators (<code>:append</code> and <code>:prepend</code>) <strong>DO NOT</strong> automatically add a space! You must include the space inside your quotes, otherwise you will merge strings together (e.g., <code>busyboxdropbear</code>).</p><p><strong>Correct:</strong> <code>IMAGE_INSTALL:append = &quot; curl&quot;</code><strong>Wrong:</strong> <code>IMAGE_INSTALL:append = &quot;curl&quot;</code></p></div><hr><h2 id="_3-creating-a-custom-software-layer" tabindex="-1">3. Creating a Custom Software Layer <a class="header-anchor" href="#_3-creating-a-custom-software-layer" aria-label="Permalink to &quot;3. Creating a Custom Software Layer&quot;">​</a></h2><p>Never put your custom recipes, images, or machine definitions directly into the <code>meta</code> (OE-Core) or <code>meta-yocto-bsp</code> layers. When you update the Yocto Project to a new release, your changes will be overwritten or cause massive Git conflicts.</p><p>Instead, isolate your project into a custom layer.</p><h3 id="step-1-create-the-layer" tabindex="-1">Step 1: Create the Layer <a class="header-anchor" href="#step-1-create-the-layer" aria-label="Permalink to &quot;Step 1: Create the Layer&quot;">​</a></h3><p>The <code>bitbake-layers</code> command line tool generates the correct directory structure and boilerplate <code>layer.conf</code> file automatically.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/poky/build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../meta-custom</span></span></code></pre></div><h3 id="step-2-inspect-the-generated-layer-conf" tabindex="-1">Step 2: Inspect the Generated <code>layer.conf</code> <a class="header-anchor" href="#step-2-inspect-the-generated-layer-conf" aria-label="Permalink to &quot;Step 2: Inspect the Generated \`layer.conf\`&quot;">​</a></h3><p>Open <code>../meta-custom/conf/layer.conf</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># We have a conf and classes directory, add to BBPATH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BBPATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;:\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAYERDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># We have recipes-* directories, add to BBFILES</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BBFILES</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAYERDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/recipes-*/*/*.bb </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAYERDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/recipes-*/*/*.bbappend&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BBFILE_COLLECTIONS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;meta-custom&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BBFILE_PATTERN_meta-custom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;^\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAYERDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BBFILE_PRIORITY_meta-custom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;6&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LAYERDEPENDS_meta-custom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;core&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LAYERSERIES_COMPAT_meta-custom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;kirkstone&quot;</span></span></code></pre></div><p><em>Notice how <code>BBFILE_PRIORITY</code> determines precedence when two layers provide the same recipe.</em></p><h3 id="step-3-add-the-layer-to-your-build" tabindex="-1">Step 3: Add the Layer to Your Build <a class="header-anchor" href="#step-3-add-the-layer-to-your-build" aria-label="Permalink to &quot;Step 3: Add the Layer to Your Build&quot;">​</a></h3><p>Even though you created the layer, BitBake won&#39;t scan it until it&#39;s added to <code>bblayers.conf</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../meta-custom</span></span></code></pre></div><p>Verify it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-layers</span></span></code></pre></div><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 6.1: Using <code>bitbake -e</code> to Debug Variables</p><p>The <code>bitbake -e</code> command prints the fully expanded environment for a recipe, showing exactly where a variable was modified.</p><ol><li>Run <code>bitbake -e core-image-minimal | grep ^IMAGE_INSTALL=</code></li><li>Run <code>bitbake -e core-image-minimal | grep ^MACHINE=</code></li><li>Try adding <code>IMAGE_INSTALL:append = &quot; curl&quot;</code> to your <code>local.conf</code>. Run the command again and observe the change.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 6.2: Scaffold Your First Layer</p><ol><li>Use <code>bitbake-layers create-layer</code> to create a new layer named <code>meta-myproject</code> in the <code>poky/</code> root directory.</li><li>Add it to your <code>bblayers.conf</code>.</li><li>Create the directories: <code>mkdir -p ../meta-myproject/recipes-core/images/</code> (we will use this in Day 7).</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>BitBake User Manual: Syntax</td><td><a href="https://docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-metadata.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-metadata.html</a></td></tr><tr><td>Creating a General Layer</td><td><a href="https://docs.yoctoproject.org/dev-manual/layers.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/layers.html</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day5-raspberry-pi-hardware-bringup">← Day 5: Raspberry Pi Hardware Bring-Up</a><a href="/day7-custom-image-recipes-and-features">Day 7: Custom Image Recipes &amp; Image Features →</a></div>`,41)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
